@SpringBootTest
@EmbeddedKafka(
        partitions = 3,
        topics = { "orders", "orders.DLT" },
        bootstrapServersProperty = "spring.kafka.bootstrap-servers")
@DirtiesContext(classMode = AFTER_EACH_TEST_METHOD)
class OrderListenerEmbeddedTest {

    @Autowired KafkaTemplate<String, OrderEvent> template;
    @Autowired InventoryRepository repository;

    @Test
    void 재고가_줄어든다() {
        template.send("orders", "A-1", new OrderEvent("A-1", 3));

        await().atMost(Duration.ofSeconds(10))
               .untilAsserted(() -> assertThat(repository.qtyOf("A-1")).isEqualTo(97));
    }
}

